SELECT gen_random_uuid()::text, 'formula', '$I_b = \frac{\text{MVA}_b}{\sqrt3\,\text{kV}_b}$', 'Base Current', '$I_{base} = \frac{\text{MVA}_{base}}{\sqrt3\,\text{kV}_{base}}\ (\text{kA}),\qquad I = I_{pu}I_{base}$', '$\text{kA}$', 'The current that is 1 per unit in a voltage zone, to turn per-unit answers back into amperes.', '[{"symbol":"$\\text{MVA}_{base}$","meaning":"three-phase base power","unit":null},{"symbol":"$\\text{kV}_{base}$","meaning":"line-to-line base voltage of that zone","unit":null}]'::jsonb, 'MVA over kV gives kA. Every zone has its own current base, like its own voltage base.', 'EE', t."id", (SELECT s."id" FROM "SyllabusSubtopic" s JOIN "Topic" t ON t."id" = s."topicId" WHERE t."name" = 'Power System Analysis' AND t."subject" = 'EE' AND s."normKey" = 'per-unit system' AND s."active"), NULL, false, 'PENDING', now(), now()
FROM "Topic" t WHERE t."name" = 'Power System Analysis' AND t."subject" = 'EE'
ON CONFLICT ("kind", "subject", "name") DO NOTHING;
