SELECT gen_random_uuid()::text, 'formula', '$Z = \frac{V^2}{S^*}$', 'Load Impedance from Its Rating', '$Z = \frac{|V|^2}{S^*} = \frac{|V|^2}{|S|}(\cos\theta + j\sin\theta)\ (\text{lagging load})$', '$\Omega$', 'A constant-impedance load for the impedance diagram, from its MVA and power factor.', '[{"symbol":"$V$","meaning":"voltage the load is rated at","unit":"$\\text{V}$"},{"symbol":"$S$","meaning":"complex power it takes","unit":"$\\text{VA}$"},{"symbol":"$\\theta$","meaning":"power-factor angle","unit":null}]'::jsonb, 'Use the conjugate: a lagging load is R + jX. In per unit: Z_pu = V_pu²/S_pu*.', 'EE', t."id", (SELECT s."id" FROM "SyllabusSubtopic" s JOIN "Topic" t ON t."id" = s."topicId" WHERE t."name" = 'Power System Analysis' AND t."subject" = 'EE' AND s."normKey" = 'one-line and impedance diagrams' AND s."active"), NULL, false, 'PENDING', now(), now()
FROM "Topic" t WHERE t."name" = 'Power System Analysis' AND t."subject" = 'EE'
ON CONFLICT ("kind", "subject", "name") DO NOTHING;
