SELECT gen_random_uuid()::text, 'formula', '$D_s^b = \sqrt{D_sd}$', 'GMR of a Bundled Conductor', '$\text{2: } \sqrt{D_sd};\quad \text{3: } \sqrt[3]{D_sd^2};\quad \text{4: } 1.09\sqrt[4]{D_sd^3}$', '$\text{m}$', 'The GMR of a bundle, which lowers the line''s inductance and raises its capacitance.', '[{"symbol":"$D_s$","meaning":"GMR of one subconductor (0.7788r if solid)","unit":"$\\text{m}$"},{"symbol":"$d$","meaning":"spacing between subconductors","unit":"$\\text{m}$"}]'::jsonb, 'For capacitance use the radius r in place of D_s. Bundling also cuts corona.', 'EE', t."id", (SELECT s."id" FROM "SyllabusSubtopic" s JOIN "Topic" t ON t."id" = s."topicId" WHERE t."name" = 'Power System Analysis' AND t."subject" = 'EE' AND s."normKey" = 'line resistance, inductance and capacitance' AND s."active"), NULL, false, 'PENDING', now(), now()
FROM "Topic" t WHERE t."name" = 'Power System Analysis' AND t."subject" = 'EE'
ON CONFLICT ("kind", "subject", "name") DO NOTHING;
