SELECT gen_random_uuid()::text, 'formula', '$X_L = 0.0754\ln\frac{D_{eq}}{D_s}$', 'Inductive Reactance per Kilometre', '$X_L = 2\pi f(2 \times 10^{-7})\ln\frac{D_{eq}}{D_s}\ \Omega/\text{m} = 0.0754\ln\frac{D_{eq}}{D_s}\ \Omega/\text{km}\ (60\ \text{Hz})$', '$\Omega/\text{km}$', 'Series reactance per phase per kilometre of line.', '[{"symbol":"$f$","meaning":"frequency","unit":"$\\text{Hz}$"},{"symbol":"$D_{eq}$","meaning":"GMD","unit":"$\\text{m}$"},{"symbol":"$D_s$","meaning":"GMR","unit":"$\\text{m}$"}]'::jsonb, 'Typical overhead lines are about 0.3 to 0.5 Ω/km at 60 Hz; it grows only with the log of spacing.', 'EE', t."id", (SELECT s."id" FROM "SyllabusSubtopic" s JOIN "Topic" t ON t."id" = s."topicId" WHERE t."name" = 'Power System Analysis' AND t."subject" = 'EE' AND s."normKey" = 'line resistance, inductance and capacitance' AND s."active"), NULL, false, 'PENDING', now(), now()
