SELECT gen_random_uuid()::text, 'formula', '$C_{ab} = \frac{\pi\varepsilon_0}{\ln(D/r)}$', 'Capacitance of a Single-Phase Line', '$C_{ab} = \frac{\pi\varepsilon_0}{\ln(D/r)},\qquad C_n = 2C_{ab}\ (\text{to neutral})$', '$\text{F/m}$', 'Line-to-line capacitance of a two-wire line, and the capacitance to the neutral plane between them.', '[{"symbol":"$D$","meaning":"conductor spacing","unit":"$\\text{m}$"},{"symbol":"$r$","meaning":"conductor radius","unit":"$\\text{m}$"}]'::jsonb, 'Capacitance to neutral is TWICE line-to-line: two capacitances to neutral in series make C_ab.', 'EE', t."id", (SELECT s."id" FROM "SyllabusSubtopic" s JOIN "Topic" t ON t."id" = s."topicId" WHERE t."name" = 'Power System Analysis' AND t."subject" = 'EE' AND s."normKey" = 'line resistance, inductance and capacitance' AND s."active"), NULL, false, 'PENDING', now(), now()
