SELECT gen_random_uuid()::text, 'formula', '$I_c = 2\pi fC_nV_{LN}\ell$', 'Line Charging Current and Reactive Power', '$I_c = 2\pi fC_nV_{LN}\ell,\qquad Q_c = 2\pi fC_nV_{LL}^2\ell\ (\text{three phase})$', '$\text{A}$', 'The current and vars a line''s own capacitance draws, even with no load.', '[{"symbol":"$C_n$","meaning":"capacitance to neutral per length","unit":"$\\text{F/m}$"},{"symbol":"$V_{LN}, V_{LL}$","meaning":"phase and line voltages","unit":"$\\text{V}$"},{"symbol":"$\\ell$","meaning":"line length","unit":"$\\text{m}$"}]'::jsonb, 'Charging vars grow with V²: long EHV lines and cables need shunt reactors at light load.', 'EE', t."id", (SELECT s."id" FROM "SyllabusSubtopic" s JOIN "Topic" t ON t."id" = s."topicId" WHERE t."name" = 'Power System Analysis' AND t."subject" = 'EE' AND s."normKey" = 'line resistance, inductance and capacitance' AND s."active"), NULL, false, 'PENDING', now(), now()
