SELECT gen_random_uuid()::text, 'formula', '$V_s = V_r + IZ$', 'Short Transmission Line', '$\mathbf{V}_s = \mathbf{V}_r + \mathbf{I}Z,\qquad \mathbf{I}_s = \mathbf{I}_r\quad (\ell < 80\ \text{km})$', '$\text{V}$', 'A line short enough to ignore its capacitance: a series impedance.', '[{"symbol":"$\\mathbf{V}_s, \\mathbf{V}_r$","meaning":"sending- and receiving-end phase voltages","unit":"$\\text{V}$"},{"symbol":"$Z$","meaning":"total series impedance per phase","unit":"$\\Omega$"}]'::jsonb, 'Work per phase (line-to-neutral) and use the same current at both ends.', 'EE', t."id", (SELECT s."id" FROM "SyllabusSubtopic" s JOIN "Topic" t ON t."id" = s."topicId" WHERE t."name" = 'Power System Analysis' AND t."subject" = 'EE' AND s."normKey" = 'short, medium and long lines' AND s."active"), NULL, false, 'PENDING', now(), now()
