SELECT gen_random_uuid()::text, 'formula', '$\pi: A = 1 + \frac{YZ}{2},\ B = Z$', 'Nominal π and T Lines', '$\pi: A = D = 1 + \frac{YZ}{2},\ B = Z,\ C = Y\left(1 + \frac{YZ}{4}\right);\quad T: A = D = 1 + \frac{YZ}{2},\ B = Z\left(1 + \frac{YZ}{4}\right),\ C = Y$', NULL, 'Medium lines (80–250 km): the shunt admittance lumped half at each end (π) or in the middle (T).', '[{"symbol":"$Z$","meaning":"total series impedance","unit":"$\\Omega$"},{"symbol":"$Y$","meaning":"total shunt admittance","unit":"$\\text{S}$"}]'::jsonb, 'Both give AD − BC = 1. The nominal π is the one used in most problems.', 'EE', t."id", (SELECT s."id" FROM "SyllabusSubtopic" s JOIN "Topic" t ON t."id" = s."topicId" WHERE t."name" = 'Power System Analysis' AND t."subject" = 'EE' AND s."normKey" = 'short, medium and long lines' AND s."active"), NULL, true, 'PENDING', now(), now()
FROM "Topic" t WHERE t."name" = 'Power System Analysis' AND t."subject" = 'EE'
ON CONFLICT ("kind", "subject", "name") DO NOTHING;
