SELECT gen_random_uuid()::text, 'formula', '$A = \cosh\gamma\ell,\ B = Z_c\sinh\gamma\ell$', 'Long Line Equations', '$A = D = \cosh\gamma\ell,\quad B = Z_c\sinh\gamma\ell,\quad C = \frac{\sinh\gamma\ell}{Z_c};\quad \gamma = \sqrt{zy},\ Z_c = \sqrt{z/y}$', NULL, 'The exact ABCD constants of a line, with R, L, G and C spread along it.', '[{"symbol":"$z, y$","meaning":"series impedance and shunt admittance per length","unit":null},{"symbol":"$\\gamma$","meaning":"propagation constant α + jβ","unit":"$\\text{1/m}$"},{"symbol":"$\\ell$","meaning":"length","unit":"$\\text{m}$"}]'::jsonb, 'β = 2π/λ; at 60 Hz the wavelength of an overhead line is about 5000 km.', 'EE', t."id", (SELECT s."id" FROM "SyllabusSubtopic" s JOIN "Topic" t ON t."id" = s."topicId" WHERE t."name" = 'Power System Analysis' AND t."subject" = 'EE' AND s."normKey" = 'short, medium and long lines' AND s."active"), NULL, true, 'PENDING', now(), now()
FROM "Topic" t WHERE t."name" = 'Power System Analysis' AND t."subject" = 'EE'
