SELECT gen_random_uuid()::text, 'formula', '$Z'' = Z\frac{\sinh\gamma\ell}{\gamma\ell}$', 'Equivalent π of a Long Line', '$Z'' = Z\frac{\sinh\gamma\ell}{\gamma\ell},\qquad \frac{Y''}{2} = \frac{Y}{2}\frac{\tanh(\gamma\ell/2)}{\gamma\ell/2}$', NULL, 'A π circuit that behaves exactly like the long line at its terminals.', '[{"symbol":"$Z, Y$","meaning":"total series impedance and shunt admittance (zℓ, yℓ)","unit":null},{"symbol":"$\\gamma\\ell$","meaning":"propagation constant times length","unit":null}]'::jsonb, 'For short lengths the correction factors approach 1 and it becomes the nominal π.', 'EE', t."id", (SELECT s."id" FROM "SyllabusSubtopic" s JOIN "Topic" t ON t."id" = s."topicId" WHERE t."name" = 'Power System Analysis' AND t."subject" = 'EE' AND s."normKey" = 'short, medium and long lines' AND s."active"), NULL, true, 'PENDING', now(), now()
FROM "Topic" t WHERE t."name" = 'Power System Analysis' AND t."subject" = 'EE'
