SELECT gen_random_uuid()::text, 'formula', '$\text{VR} = \frac{|V_s|/|A| - |V_{r,FL}|}{|V_{r,FL}|}$', 'Regulation from ABCD Constants', '$|V_{r,NL}| = \frac{|V_s|}{|A|},\qquad \text{VR} = \frac{|V_s|/|A| - |V_{r,FL}|}{|V_{r,FL}|}$', NULL, 'Line regulation: with the load removed and V_s held, the receiving voltage becomes V_s/A.', '[{"symbol":"$V_s$","meaning":"sending-end voltage at full load","unit":"$\\text{V}$"},{"symbol":"$A$","meaning":"line constant A","unit":null},{"symbol":"$V_{r,FL}$","meaning":"receiving voltage at full load","unit":"$\\text{V}$"}]'::jsonb, 'For a short line A = 1; with capacitance |A| < 1 and the no-load voltage rises.', 'EE', t."id", (SELECT s."id" FROM "SyllabusSubtopic" s JOIN "Topic" t ON t."id" = s."topicId" WHERE t."name" = 'Power System Analysis' AND t."subject" = 'EE' AND s."normKey" = 'abcd constants' AND s."active"), NULL, true, 'PENDING', now(), now()
FROM "Topic" t WHERE t."name" = 'Power System Analysis' AND t."subject" = 'EE'
