SELECT gen_random_uuid()::text, 'formula', '$[T] = [T_1][T_2]$', 'Networks in Cascade', '$\begin{bmatrix}A & B\\ C & D\end{bmatrix} = \begin{bmatrix}A_1 & B_1\\ C_1 & D_1\end{bmatrix}\begin{bmatrix}A_2 & B_2\\ C_2 & D_2\end{bmatrix}$', NULL, 'A transformer, line and another transformer in series combine by multiplying their ABCD matrices.', '[{"symbol":"$[T_1], [T_2]$","meaning":"ABCD matrices in order from the sending end","unit":null}]'::jsonb, 'Order matters: sending end first. The product still has AD − BC = 1.', 'EE', t."id", (SELECT s."id" FROM "SyllabusSubtopic" s JOIN "Topic" t ON t."id" = s."topicId" WHERE t."name" = 'Power System Analysis' AND t."subject" = 'EE' AND s."normKey" = 'abcd constants' AND s."active"), NULL, true, 'PENDING', now(), now()
