SELECT gen_random_uuid()::text, 'formula', '$S_r = \frac{V_sV_r}{B}\angle(\beta - \delta) - \dots$', 'Receiving-End Power Circle', '$P_r + jQ_r = \frac{|V_s||V_r|}{|B|}\angle(\beta - \delta) - \frac{|A||V_r|^2}{|B|}\angle(\beta - \alpha)$', NULL, 'Receiving-end power as a circle: centre fixed by A, B and V_r, radius V_sV_r/B, position by δ.', '[{"symbol":"$A\\angle\\alpha,\\ B\\angle\\beta$","meaning":"line constants A and B, magnitude and angle","unit":null},{"symbol":"$\\delta$","meaning":"angle of V_s ahead of V_r","unit":null},{"symbol":"$V_s, V_r$","meaning":"line voltages for three-phase power","unit":"$\\text{V}$"}]'::jsonb, 'Maximum P_r at δ = β: |V_s||V_r|/|B| − |A||V_r|² cos(β − α)/|B|.', 'EE', t."id", (SELECT s."id" FROM "SyllabusSubtopic" s JOIN "Topic" t ON t."id" = s."topicId" WHERE t."name" = 'Power System Analysis' AND t."subject" = 'EE' AND s."normKey" = 'power circle diagrams' AND s."active"), NULL, true, 'PENDING', now(), now()
