SELECT gen_random_uuid()::text, 'formula', '$Y_{ii} = \sum y,\ Y_{ij} = -y_{ij}$', 'Bus Admittance Matrix', '$Y_{ii} = \sum_k y_{ik} + y_{i0},\qquad Y_{ij} = -y_{ij},\qquad \mathbf{I} = Y_{bus}\mathbf{V}$', NULL, 'The nodal equations of a network, built by inspection.', '[{"symbol":"$y_{ij}$","meaning":"admittance of the branch between buses i and j","unit":"$\\text{S or pu}$"},{"symbol":"$y_{i0}$","meaning":"shunt admittance at bus i (line charging, capacitors)","unit":null}]'::jsonb, 'Diagonal: everything connected to the bus. Off-diagonal: MINUS the branch between. Symmetric without phase shifters.', 'EE', t."id", (SELECT s."id" FROM "SyllabusSubtopic" s JOIN "Topic" t ON t."id" = s."topicId" WHERE t."name" = 'Power System Analysis' AND t."subject" = 'EE' AND s."normKey" = 'bus admittance matrix' AND s."active"), NULL, true, 'PENDING', now(), now()
