SELECT gen_random_uuid()::text, 'formula', '$Y_{red} = Y_{AA} - Y_{AB}Y_{BB}^{-1}Y_{BA}$', 'Kron Reduction', '$Y_{red} = Y_{AA} - Y_{AB}Y_{BB}^{-1}Y_{BA}\quad (\text{buses } B \text{ with no injection removed})$', NULL, 'Eliminates buses that inject no current, keeping the same behaviour at the rest.', '[{"symbol":"$Y_{AA}, Y_{AB}, Y_{BA}, Y_{BB}$","meaning":"blocks of Y_bus for kept (A) and removed (B) buses","unit":null}]'::jsonb, 'One bus at a time: Y_ij(new) = Y_ij − Y_ik Y_kj / Y_kk.', 'EE', t."id", (SELECT s."id" FROM "SyllabusSubtopic" s JOIN "Topic" t ON t."id" = s."topicId" WHERE t."name" = 'Power System Analysis' AND t."subject" = 'EE' AND s."normKey" = 'bus admittance matrix' AND s."active"), NULL, true, 'PENDING', now(), now()
