SELECT gen_random_uuid()::text, 'formula', '$P_i - jQ_i = V_i^*\sum_j Y_{ij}V_j$', 'Power-Flow Equations', '$P_i - jQ_i = V_i^*\sum_j Y_{ij}V_j;\quad P_i = \sum_j|V_iV_jY_{ij}|\cos(\theta_{ij} - \delta_i + \delta_j)$', NULL, 'The nonlinear equations a load flow solves: injected power at every bus from the voltages.', '[{"symbol":"$V_i = |V_i|\\angle\\delta_i$","meaning":"bus voltage, pu","unit":null},{"symbol":"$Y_{ij} = |Y_{ij}|\\angle\\theta_{ij}$","meaning":"Y-bus element","unit":null},{"symbol":"$P_i, Q_i$","meaning":"net injection at bus i, pu","unit":null}]'::jsonb, 'Slack bus: V and δ known. PV (generator) bus: P and |V|. PQ (load) bus: P and Q.', 'EE', t."id", (SELECT s."id" FROM "SyllabusSubtopic" s JOIN "Topic" t ON t."id" = s."topicId" WHERE t."name" = 'Power System Analysis' AND t."subject" = 'EE' AND s."normKey" = 'load flow' AND s."active"), NULL, true, 'PENDING', now(), now()
