SELECT gen_random_uuid()::text, 'formula', '$V_i = \frac{1}{Y_{ii}}[\frac{S_i^*}{V_i^*} - \dots]$', 'Gauss-Seidel Update', '$V_i^{(k+1)} = \frac{1}{Y_{ii}}\left[\frac{P_i - jQ_i}{V_i^{*(k)}} - \sum_{j \ne i}Y_{ij}V_j\right]$', NULL, 'One Gauss-Seidel step for a load bus, using the newest voltages as soon as they are found.', '[{"symbol":"$V_j$","meaning":"latest values of the other bus voltages","unit":null},{"symbol":"$P_i, Q_i$","meaning":"scheduled injection (load is negative)","unit":null}]'::jsonb, 'Load injections are NEGATIVE. Acceleration factors of about 1.6 speed it up.', 'EE', t."id", (SELECT s."id" FROM "SyllabusSubtopic" s JOIN "Topic" t ON t."id" = s."topicId" WHERE t."name" = 'Power System Analysis' AND t."subject" = 'EE' AND s."normKey" = 'load flow' AND s."active"), NULL, true, 'PENDING', now(), now()
FROM "Topic" t WHERE t."name" = 'Power System Analysis' AND t."subject" = 'EE'
ON CONFLICT ("kind", "subject", "name") DO NOTHING;
