SELECT gen_random_uuid()::text, 'formula', '$[\Delta\delta;\ \Delta V] = J^{-1}[\Delta P;\ \Delta Q]$', 'Newton-Raphson Step', '$\begin{bmatrix}\Delta\boldsymbol\delta\\ \Delta|\mathbf{V}|\end{bmatrix} = J^{-1}\begin{bmatrix}\Delta\mathbf{P}\\ \Delta\mathbf{Q}\end{bmatrix},\qquad J = \begin{bmatrix}\partial P/\partial\delta & \partial P/\partial|V|\\ \partial Q/\partial\delta & \partial Q/\partial|V|\end{bmatrix}$', NULL, 'Newton-Raphson load flow: correct all angles and magnitudes at once from the mismatches.', '[{"symbol":"$\\Delta P, \\Delta Q$","meaning":"mismatches: scheduled minus calculated","unit":null},{"symbol":"$J$","meaning":"Jacobian","unit":null}]'::jsonb, 'Converges in a few iterations, almost independent of system size.', 'EE', t."id", (SELECT s."id" FROM "SyllabusSubtopic" s JOIN "Topic" t ON t."id" = s."topicId" WHERE t."name" = 'Power System Analysis' AND t."subject" = 'EE' AND s."normKey" = 'load flow' AND s."active"), NULL, true, 'PENDING', now(), now()
FROM "Topic" t WHERE t."name" = 'Power System Analysis' AND t."subject" = 'EE'
ON CONFLICT ("kind", "subject", "name") DO NOTHING;
