SELECT gen_random_uuid()::text, 'formula', '$P_{ij} \approx \frac{\delta_i - \delta_j}{X_{ij}}$', 'DC Load Flow', '$P_{ij} \approx \frac{\delta_i - \delta_j}{X_{ij}}\ (\text{pu, radians}),\qquad \mathbf{P} = B''\boldsymbol\delta$', NULL, 'A linear estimate of real-power flows: flat voltages, small angles, no resistance.', '[{"symbol":"$\\delta_i - \\delta_j$","meaning":"angle difference across the line, rad","unit":null},{"symbol":"$X_{ij}$","meaning":"line reactance, pu","unit":null}]'::jsonb, 'Real power flows from the leading angle to the lagging; reactive power from higher to lower voltage.', 'EE', t."id", (SELECT s."id" FROM "SyllabusSubtopic" s JOIN "Topic" t ON t."id" = s."topicId" WHERE t."name" = 'Power System Analysis' AND t."subject" = 'EE' AND s."normKey" = 'load flow' AND s."active"), NULL, true, 'PENDING', now(), now()
FROM "Topic" t WHERE t."name" = 'Power System Analysis' AND t."subject" = 'EE'
