SELECT gen_random_uuid()::text, 'formula', '$I_f = \frac{V_f}{Z_{th} + Z_f}$', 'Symmetrical Fault Current', '$I_f = \frac{V_f}{Z_{th} + Z_f}\ (\text{pu}),\qquad I = I_{f,pu}\frac{\text{MVA}_{base}}{\sqrt3\,\text{kV}_{base}}$', NULL, 'The current of a balanced three-phase fault, from the Thévenin equivalent at the fault.', '[{"symbol":"$V_f$","meaning":"prefault voltage at the fault, per unit","unit":null},{"symbol":"$Z_{th}$","meaning":"Thévenin impedance at the fault (positive sequence), pu","unit":null},{"symbol":"$Z_f$","meaning":"fault impedance, pu","unit":null}]'::jsonb, 'Use subtransient reactances for the first cycles. With V_f = 1, I_f = 1/Z_th pu.', 'EE', t."id", (SELECT s."id" FROM "SyllabusSubtopic" s JOIN "Topic" t ON t."id" = s."topicId" WHERE t."name" = 'Power System Analysis' AND t."subject" = 'EE' AND s."normKey" = 'symmetrical faults' AND s."active"), NULL, true, 'PENDING', now(), now()
