SELECT gen_random_uuid()::text, 'formula', '$I'''' = \frac{E''''}{X''''_d + X_{ext}}$', 'Subtransient Fault Current of a Generator', '$I'''' = \frac{E''''}{X''''_d + X_{ext}},\quad I'' = \frac{E''}{X''_d + X_{ext}},\quad I_{ss} = \frac{E}{X_d + X_{ext}}$', NULL, 'Fault current falls from subtransient through transient to steady state as the rotor''s flux decays.', '[{"symbol":"$E'''', E'', E$","meaning":"internal voltages behind each reactance, pu","unit":null},{"symbol":"$X''''_d, X''_d, X_d$","meaning":"subtransient, transient and synchronous reactances, pu","unit":null},{"symbol":"$X_{ext}$","meaning":"external reactance to the fault, pu","unit":null}]'::jsonb, 'X″ < X′ < X_d: breakers and relays are set from the subtransient value.', 'EE', t."id", (SELECT s."id" FROM "SyllabusSubtopic" s JOIN "Topic" t ON t."id" = s."topicId" WHERE t."name" = 'Power System Analysis' AND t."subject" = 'EE' AND s."normKey" = 'symmetrical faults' AND s."active"), NULL, true, 'PENDING', now(), now()
