SELECT gen_random_uuid()::text, 'formula', '$V_i = V_f - Z_{ik}I_f$', 'Bus Voltages During a Fault (Z-bus)', '$I_f = \frac{V_f}{Z_{kk} + Z_f},\qquad V_i = V_f - Z_{ik}I_f$', NULL, 'With Z_bus = Y_bus⁻¹, the fault current and every bus voltage come straight from one column.', '[{"symbol":"$Z_{kk}$","meaning":"Z-bus diagonal at the faulted bus k (its Thévenin impedance), pu","unit":null},{"symbol":"$Z_{ik}$","meaning":"Z-bus element between buses i and k, pu","unit":null},{"symbol":"$V_f$","meaning":"prefault voltage at the fault, per unit","unit":null},{"symbol":"$Z_f$","meaning":"fault impedance, pu","unit":null}]'::jsonb, 'The faulted bus itself drops to Z_f·I_f; a bolted fault takes it to zero.', 'EE', t."id", (SELECT s."id" FROM "SyllabusSubtopic" s JOIN "Topic" t ON t."id" = s."topicId" WHERE t."name" = 'Power System Analysis' AND t."subject" = 'EE' AND s."normKey" = 'symmetrical faults' AND s."active"), NULL, true, 'PENDING', now(), now()
