SELECT gen_random_uuid()::text, 'formula', '$S = 3(V_0I_0^* + V_1I_1^* + V_2I_2^*)$', 'Power in Symmetrical Components', '$S = V_aI_a^* + V_bI_b^* + V_cI_c^* = 3(V_0I_0^* + V_1I_1^* + V_2I_2^*)$', NULL, 'Three-phase power from the sequence quantities: the sequences carry power independently.', '[{"symbol":"$V_0, V_1, V_2$","meaning":"sequence voltages of phase a","unit":"$\\text{V}$"},{"symbol":"$I_0, I_1, I_2$","meaning":"sequence currents of phase a","unit":"$\\text{A}$"}]'::jsonb, 'The factor 3 comes from the 1/3 in the transformation.', 'EE', t."id", (SELECT s."id" FROM "SyllabusSubtopic" s JOIN "Topic" t ON t."id" = s."topicId" WHERE t."name" = 'Power System Analysis' AND t."subject" = 'EE' AND s."normKey" = 'symmetrical components' AND s."active"), NULL, true, 'PENDING', now(), now()
