SELECT gen_random_uuid()::text, 'formula', '$Z_0 = Z_{0,eq} + 3Z_n$', 'Neutral Impedance in the Zero Sequence', '$Z_0 = Z_{0,eq} + 3Z_n\quad (\text{grounded-Y through } Z_n)$', '$\Omega$', 'A neutral impedance appears THREE times in the zero-sequence network, because 3I₀ flows through it.', '[{"symbol":"$Z_n$","meaning":"neutral grounding impedance","unit":"$\\Omega$"},{"symbol":"$Z_{0,eq}$","meaning":"the equipment''s own zero-sequence impedance","unit":"$\\Omega$"}]'::jsonb, 'Ungrounded Y or delta: zero-sequence current cannot flow; Δ-Y transformers block it between sides.', 'EE', t."id", (SELECT s."id" FROM "SyllabusSubtopic" s JOIN "Topic" t ON t."id" = s."topicId" WHERE t."name" = 'Power System Analysis' AND t."subject" = 'EE' AND s."normKey" = 'symmetrical components' AND s."active"), NULL, false, 'PENDING', now(), now()
FROM "Topic" t WHERE t."name" = 'Power System Analysis' AND t."subject" = 'EE'
