SELECT gen_random_uuid()::text, 'formula', '$I_f = \frac{3V_f}{Z_1 + Z_2 + Z_0 + 3Z_f}$', 'Single Line-to-Ground Fault', '$I_{a1} = I_{a2} = I_{a0} = \frac{V_f}{Z_1 + Z_2 + Z_0 + 3Z_f},\qquad I_f = 3I_{a0}$', NULL, 'The commonest fault: the three sequence networks in series.', '[{"symbol":"$V_f$","meaning":"prefault voltage at the fault, per unit","unit":null},{"symbol":"$Z_1, Z_2, Z_0$","meaning":"positive-, negative- and zero-sequence Thévenin impedances at the fault, pu","unit":null},{"symbol":"$Z_f$","meaning":"fault impedance, pu","unit":null}]'::jsonb, 'On a solidly grounded system with Z₀ < Z₁ it can exceed the three-phase fault current.', 'EE', t."id", (SELECT s."id" FROM "SyllabusSubtopic" s JOIN "Topic" t ON t."id" = s."topicId" WHERE t."name" = 'Power System Analysis' AND t."subject" = 'EE' AND s."normKey" = 'unsymmetrical faults' AND s."active"), NULL, true, 'PENDING', now(), now()
