SELECT gen_random_uuid()::text, 'formula', '$I_b = -j\sqrt3\frac{V_f}{Z_1 + Z_2 + Z_f}$', 'Line-to-Line Fault', '$I_{a1} = -I_{a2} = \frac{V_f}{Z_1 + Z_2 + Z_f},\quad I_{a0} = 0,\quad I_b = -I_c = -j\sqrt3I_{a1}$', NULL, 'Two phases shorted together: positive and negative networks in parallel, no zero sequence.', '[{"symbol":"$V_f$","meaning":"prefault voltage at the fault, per unit","unit":null},{"symbol":"$Z_1, Z_2$","meaning":"positive- and negative-sequence impedances, pu","unit":null},{"symbol":"$Z_f$","meaning":"fault impedance, pu","unit":null}]'::jsonb, 'With Z₁ = Z₂ it is √3/2 = 0.866 of the three-phase fault current.', 'EE', t."id", (SELECT s."id" FROM "SyllabusSubtopic" s JOIN "Topic" t ON t."id" = s."topicId" WHERE t."name" = 'Power System Analysis' AND t."subject" = 'EE' AND s."normKey" = 'unsymmetrical faults' AND s."active"), NULL, true, 'PENDING', now(), now()
FROM "Topic" t WHERE t."name" = 'Power System Analysis' AND t."subject" = 'EE'
