INSERT INTO "ReferenceCard" ("id", "kind", "symbol", "name", "formulaLatex", "valueUnit", "description", "variables", "purposeExamTip", "subject", "topicId", "subtopicId", "subtopicTag", "dimensionless", "status", "createdAt", "updatedAt")
SELECT gen_random_uuid()::text, 'formula', '$I_{a1} = \frac{V_f}{Z_1 + Z_2\|(Z_0 + 3Z_f)}$', 'Double Line-to-Ground Fault', '$I_{a1} = \frac{V_f}{Z_1 + \frac{Z_2(Z_0 + 3Z_f)}{Z_2 + Z_0 + 3Z_f}},\quad I_{a2} = -I_{a1}\frac{Z_0 + 3Z_f}{Z_2 + Z_0 + 3Z_f},\quad I_{a0} = -I_{a1}\frac{Z_2}{Z_2 + Z_0 + 3Z_f}$', NULL, 'Two phases to ground: the negative and zero networks in parallel, in series with the positive.', '[{"symbol":"$V_f$","meaning":"prefault voltage at the fault, per unit","unit":null},{"symbol":"$Z_1, Z_2, Z_0$","meaning":"positive-, negative- and zero-sequence Thévenin impedances at the fault, pu","unit":null},{"symbol":"$Z_f$","meaning":"fault impedance, pu","unit":null}]'::jsonb, 'Ground current = 3I_a0. Check: I_a1 + I_a2 + I_a0 = 0 because phase a carries nothing.', 'EE', t."id", (SELECT s."id" FROM "SyllabusSubtopic" s JOIN "Topic" t ON t."id" = s."topicId" WHERE t."name" = 'Power System Analysis' AND t."subject" = 'EE' AND s."normKey" = 'unsymmetrical faults' AND s."active"), NULL, true, 'PENDING', now(), now()
