SELECT gen_random_uuid()::text, 'formula', '$\frac{2H}{\omega_s}\frac{d^2\delta}{dt^2} = P_m - P_e$', 'Swing Equation', '$\frac{2H}{\omega_s}\frac{d^2\delta}{dt^2} = P_m - P_e\ (\text{pu}),\qquad H = \frac{\tfrac12J\omega_{sm}^2}{S_{rated}}$', NULL, 'How a machine''s rotor angle accelerates when mechanical and electrical power differ.', '[{"symbol":"$H$","meaning":"inertia constant, stored energy per rated VA","unit":"$\\text{s}$"},{"symbol":"$\\omega_s$","meaning":"synchronous speed, electrical","unit":"$\\text{rad/s}$"},{"symbol":"$P_m, P_e$","meaning":"mechanical input and electrical output, pu","unit":null}]'::jsonb, 'Change H to the system base: H_sys = H·S_machine/S_base. Typical H: 2–9 s.', 'EE', t."id", (SELECT s."id" FROM "SyllabusSubtopic" s JOIN "Topic" t ON t."id" = s."topicId" WHERE t."name" = 'Power System Analysis' AND t."subject" = 'EE' AND s."normKey" = 'stability and equal area' AND s."active"), NULL, true, 'PENDING', now(), now()
