SELECT gen_random_uuid()::text, 'formula', '$A_{accel} = A_{decel}$', 'Equal Area Criterion', '$\int_{\delta_0}^{\delta_c}(P_m - P_e)\,d\delta = \int_{\delta_c}^{\delta_{\max}}(P_e - P_m)\,d\delta$', NULL, 'A machine stays in step if the decelerating area after clearing can match the accelerating area during the fault.', '[{"symbol":"$\\delta_0, \\delta_c, \\delta_{\\max}$","meaning":"initial, clearing and maximum swing angles","unit":null},{"symbol":"$P_m, P_e$","meaning":"mechanical and electrical power, pu","unit":null}]'::jsonb, 'δ_max cannot pass π − δ₀ on the post-fault curve, or the machine pulls out.', 'EE', t."id", (SELECT s."id" FROM "SyllabusSubtopic" s JOIN "Topic" t ON t."id" = s."topicId" WHERE t."name" = 'Power System Analysis' AND t."subject" = 'EE' AND s."normKey" = 'stability and equal area' AND s."active"), NULL, true, 'PENDING', now(), now()
FROM "Topic" t WHERE t."name" = 'Power System Analysis' AND t."subject" = 'EE'
