INSERT INTO "ReferenceCard" ("id", "kind", "symbol", "name", "formulaLatex", "valueUnit", "description", "variables", "purposeExamTip", "subject", "topicId", "subtopicId", "subtopicTag", "dimensionless", "status", "createdAt", "updatedAt")
SELECT gen_random_uuid()::text, 'formula', '$t_{cr} = \sqrt{4H(\delta_{cr} - \delta_0)/(\omega_sP_m)}$', 'Critical Clearing Angle and Time', '$\cos\delta_{cr} = (\pi - 2\delta_0)\sin\delta_0 - \cos\delta_0,\qquad t_{cr} = \sqrt{\frac{4H(\delta_{cr} - \delta_0)}{\omega_sP_m}}$', NULL, 'For a fault that cuts the electrical output to zero and is then cleared back to the same line: the latest safe clearing.', '[{"symbol":"$\\delta_0$","meaning":"prefault angle, rad","unit":null},{"symbol":"$H$","meaning":"inertia constant","unit":"$\\text{s}$"},{"symbol":"$P_m$","meaning":"mechanical power, pu","unit":null},{"symbol":"$\\omega_s$","meaning":"synchronous speed","unit":"$\\text{rad/s}$"}]'::jsonb, 'Valid only when P_e = 0 during the fault and the post-fault curve equals the prefault one.', 'EE', t."id", (SELECT s."id" FROM "SyllabusSubtopic" s JOIN "Topic" t ON t."id" = s."topicId" WHERE t."name" = 'Power System Analysis' AND t."subject" = 'EE' AND s."normKey" = 'stability and equal area' AND s."active"), NULL, true, 'PENDING', now(), now()
FROM "Topic" t WHERE t."name" = 'Power System Analysis' AND t."subject" = 'EE'
