SELECT gen_random_uuid()::text, 'formula', '$\frac{dC_i}{dP_i} = \lambda$', 'Equal Incremental Cost', '$\frac{dC_i}{dP_i} = b_i + 2c_iP_i = \lambda\ (\text{all units}),\qquad P_i = \frac{\lambda - b_i}{2c_i},\quad \sum P_i = P_D$', NULL, 'The cheapest dispatch, ignoring losses: every unit runs at the same incremental cost.', '[{"symbol":"$C_i = a_i + b_iP_i + c_iP_i^2$","meaning":"fuel cost of unit i","unit":"$\\text{₱/h}$"},{"symbol":"$\\lambda$","meaning":"system incremental cost","unit":"$\\text{₱/MWh}$"},{"symbol":"$P_D$","meaning":"demand","unit":"$\\text{MW}$"}]'::jsonb, 'Respect unit limits: a unit at its limit is fixed there and the rest re-share at a new λ.', 'EE', t."id", (SELECT s."id" FROM "SyllabusSubtopic" s JOIN "Topic" t ON t."id" = s."topicId" WHERE t."name" = 'Power System Analysis' AND t."subject" = 'EE' AND s."normKey" = 'economic dispatch' AND s."active"), NULL, true, 'PENDING', now(), now()
FROM "Topic" t WHERE t."name" = 'Power System Analysis' AND t."subject" = 'EE'
ON CONFLICT ("kind", "subject", "name") DO NOTHING;
INSERT INTO "ReferenceCard" ("id", "kind", "symbol", "name", "formulaLatex", "valueUnit", "description", "variables", "purposeExamTip", "subject", "topicId", "subtopicId", "subtopicTag", "dimensionless", "status", "createdAt", "updatedAt")
SELECT gen_random_uuid()::text, 'formula', '$L_i\frac{dC_i}{dP_i} = \lambda$', 'Penalty Factor with Losses', '$L_i\frac{dC_i}{dP_i} = \lambda,\qquad L_i = \frac{1}{1 - \partial P_L/\partial P_i},\qquad P_L = \sum_i\sum_jP_iB_{ij}P_j$', NULL, 'With losses, a unit far from the load is penalized: it runs at a lower incremental cost.', '[{"symbol":"$L_i$","meaning":"penalty factor of unit i","unit":null},{"symbol":"$P_L$","meaning":"transmission loss","unit":"$\\text{MW}$"},{"symbol":"$B_{ij}$","meaning":"loss coefficients","unit":"$\\text{1/MW}$"}]'::jsonb, 'Now ΣP_i = P_D + P_L. A unit whose output raises losses gets L > 1.', 'EE', t."id", (SELECT s."id" FROM "SyllabusSubtopic" s JOIN "Topic" t ON t."id" = s."topicId" WHERE t."name" = 'Power System Analysis' AND t."subject" = 'EE' AND s."normKey" = 'economic dispatch' AND s."active"), NULL, true, 'PENDING', now(), now()
FROM "Topic" t WHERE t."name" = 'Power System Analysis' AND t."subject" = 'EE'
ON CONFLICT ("kind", "subject", "name") DO NOTHING;
