SELECT gen_random_uuid()::text, 'formula', '$\Delta V \approx \frac{RP + XQ}{V}$', 'Approximate Voltage Drop', '$\Delta V = |V_s| - |V_r| \approx \frac{RP + XQ}{|V_r|}$', '$\text{V}$', 'How much voltage a line drops: on transmission lines, mostly from the reactive power.', '[{"symbol":"$R, X$","meaning":"line resistance and reactance per phase","unit":"$\\Omega$"},{"symbol":"$P, Q$","meaning":"power per phase at the receiving end","unit":"$\\text{W, var}$"},{"symbol":"$V_r$","meaning":"receiving phase voltage","unit":"$\\text{V}$"}]'::jsonb, 'Since X ≫ R, voltage is held by controlling vars; frequency by controlling real power.', 'EE', t."id", (SELECT s."id" FROM "SyllabusSubtopic" s JOIN "Topic" t ON t."id" = s."topicId" WHERE t."name" = 'Power System Analysis' AND t."subject" = 'EE' AND s."normKey" = 'voltage control' AND s."active"), NULL, false, 'PENDING', now(), now()
FROM "Topic" t WHERE t."name" = 'Power System Analysis' AND t."subject" = 'EE'
ON CONFLICT ("kind", "subject", "name") DO NOTHING;
INSERT INTO "ReferenceCard" ("id", "kind", "symbol", "name", "formulaLatex", "valueUnit", "description", "variables", "purposeExamTip", "subject", "topicId", "subtopicId", "subtopicTag", "dimensionless", "status", "createdAt", "updatedAt")
SELECT gen_random_uuid()::text, 'formula', '$\Delta Q \approx \frac{V\,\Delta V}{X}$', 'Reactive Power for a Voltage Change', '$\Delta Q \approx \frac{|V|\,\Delta V}{X}\ (R \ll X),\qquad \Delta Q \approx \text{MVA}_{sc}\frac{\Delta V}{V}$', '$\text{var}$', 'The shunt vars needed to raise a bus voltage by ΔV.', '[{"symbol":"$\\Delta V$","meaning":"voltage rise wanted","unit":"$\\text{V}$"},{"symbol":"$X$","meaning":"Thévenin reactance at the bus","unit":"$\\Omega$"},{"symbol":"$\\text{MVA}_{sc}$","meaning":"short-circuit level at the bus","unit":null}]'::jsonb, 'A strong bus (high fault MVA) needs many vars for a small change: 1% on a 1000 MVA bus takes about 10 Mvar.', 'EE', t."id", (SELECT s."id" FROM "SyllabusSubtopic" s JOIN "Topic" t ON t."id" = s."topicId" WHERE t."name" = 'Power System Analysis' AND t."subject" = 'EE' AND s."normKey" = 'voltage control' AND s."active"), NULL, false, 'PENDING', now(), now()
FROM "Topic" t WHERE t."name" = 'Power System Analysis' AND t."subject" = 'EE'
ON CONFLICT ("kind", "subject", "name") DO NOTHING;
INSERT INTO "ReferenceCard" ("id", "kind", "symbol", "name", "formulaLatex", "valueUnit", "description", "variables", "purposeExamTip", "subject", "topicId", "subtopicId", "subtopicTag", "dimensionless", "status", "createdAt", "updatedAt")
SELECT gen_random_uuid()::text, 'formula', '$X_{eff} = X_L(1 - k)$', 'Series Capacitor Compensation', '$X_{eff} = X_L - X_C = X_L(1 - k),\qquad k = \frac{X_C}{X_L},\qquad P_{\max} = \frac{V_sV_r}{X_L(1 - k)}$', '$\Omega$', 'Series capacitors cancel part of a long line''s reactance, raising its power limit.', '[{"symbol":"$X_L$","meaning":"line series reactance","unit":"$\\Omega$"},{"symbol":"$X_C$","meaning":"series capacitor reactance","unit":"$\\Omega$"},{"symbol":"$k$","meaning":"degree of compensation, typically 0.25–0.75","unit":null}]'::jsonb, '50% compensation doubles the steady-state power limit. Risk: subsynchronous resonance with turbine shafts.', 'EE', t."id", (SELECT s."id" FROM "SyllabusSubtopic" s JOIN "Topic" t ON t."id" = s."topicId" WHERE t."name" = 'Power System Analysis' AND t."subject" = 'EE' AND s."normKey" = 'voltage control' AND s."active"), NULL, false, 'PENDING', now(), now()
FROM "Topic" t WHERE t."name" = 'Power System Analysis' AND t."subject" = 'EE'
ON CONFLICT ("kind", "subject", "name") DO NOTHING;
INSERT INTO "ReferenceCard" ("id", "kind", "symbol", "name", "formulaLatex", "valueUnit", "description", "variables", "purposeExamTip", "subject", "topicId", "subtopicId", "subtopicTag", "dimensionless", "status", "createdAt", "updatedAt")
SELECT gen_random_uuid()::text, 'formula', '$V_d = g_0m\delta r\ln\frac{D}{r}$', 'Disruptive Critical Voltage (Peek)', '$V_d = g_0m\delta r\ln\frac{D}{r},\quad g_0 = 21.1\ \text{kV}_{rms}/\text{cm},\quad \delta = \frac{3.92b}{273 + t}$', '$\text{kV}$', 'The phase voltage at which corona starts on a line conductor.', '[{"symbol":"$m$","meaning":"surface irregularity factor: 1 polished, 0.8–0.87 stranded","unit":null},{"symbol":"$\\delta$","meaning":"air density factor (b in cmHg, t in °C)","unit":null},{"symbol":"$r, D$","meaning":"conductor radius and spacing (cm)","unit":"$\\text{cm}$"}]'::jsonb, 'Phase (line-to-neutral) kV rms. Higher altitude or temperature lowers δ, so corona starts sooner.', 'EE', t."id", (SELECT s."id" FROM "SyllabusSubtopic" s JOIN "Topic" t ON t."id" = s."topicId" WHERE t."name" = 'Power System Analysis' AND t."subject" = 'EE' AND s."normKey" = 'corona' AND s."active"), NULL, false, 'PENDING', now(), now()
FROM "Topic" t WHERE t."name" = 'Power System Analysis' AND t."subject" = 'EE'
ON CONFLICT ("kind", "subject", "name") DO NOTHING;
INSERT INTO "ReferenceCard" ("id", "kind", "symbol", "name", "formulaLatex", "valueUnit", "description", "variables", "purposeExamTip", "subject", "topicId", "subtopicId", "subtopicTag", "dimensionless", "status", "createdAt", "updatedAt")
SELECT gen_random_uuid()::text, 'formula', '$V_v = V_d\frac{m_v}{m}(1 + 0.3/\sqrt{\delta r})$', 'Visual Critical Voltage', '$V_v = g_0m_v\delta r\left(1 + \frac{0.3}{\sqrt{\delta r}}\right)\ln\frac{D}{r}\quad (r \text{ in cm})$', '$\text{kV}$', 'The voltage at which the corona glow becomes visible, higher than the disruptive voltage.', '[{"symbol":"$m_v$","meaning":"irregularity factor for visual corona: 1 polished, 0.72 local, 0.82 general glow","unit":null},{"symbol":"$\\delta$","meaning":"air density factor","unit":null},{"symbol":"$r, D$","meaning":"radius and spacing (cm)","unit":"$\\text{cm}$"}]'::jsonb, 'Losses start at V_d, before the glow is seen.', 'EE', t."id", (SELECT s."id" FROM "SyllabusSubtopic" s JOIN "Topic" t ON t."id" = s."topicId" WHERE t."name" = 'Power System Analysis' AND t."subject" = 'EE' AND s."normKey" = 'corona' AND s."active"), NULL, false, 'PENDING', now(), now()
FROM "Topic" t WHERE t."name" = 'Power System Analysis' AND t."subject" = 'EE'
ON CONFLICT ("kind", "subject", "name") DO NOTHING;
