SELECT gen_random_uuid()::text, 'formula', '$P \propto (f + 25)\sqrt{r/D}\,(V - V_d)^2$', 'Peek''s Corona Loss', '$P =\frac{242.2}{\delta}(f + 25)\sqrt{\frac{r}{D}}(V - V_d)^2 \times 10^{-5}\ \text{kW/km/phase}$', '$\text{kW/km}$', 'Corona power loss per km per phase once the voltage exceeds the disruptive critical voltage.', '[{"symbol":"$V, V_d$","meaning":"operating and disruptive phase voltages, kV rms","unit":null},{"symbol":"$f$","meaning":"frequency","unit":"$\\text{Hz}$"},{"symbol":"$\\delta$","meaning":"air density factor","unit":null}]'::jsonb, 'Zero below V_d; it rises with the SQUARE of the excess, and greatly in foul weather.', 'EE', t."id", (SELECT s."id" FROM "SyllabusSubtopic" s JOIN "Topic" t ON t."id" = s."topicId" WHERE t."name" = 'Power System Analysis' AND t."subject" = 'EE' AND s."normKey" = 'corona' AND s."active"), NULL, false, 'PENDING', now(), now()
FROM "Topic" t WHERE t."name" = 'Power System Analysis' AND t."subject" = 'EE'
ON CONFLICT ("kind", "subject", "name") DO NOTHING;
INSERT INTO "ReferenceCard" ("id", "kind", "symbol", "name", "formulaLatex", "valueUnit", "description", "variables", "purposeExamTip", "subject", "topicId", "subtopicId", "subtopicTag", "dimensionless", "status", "createdAt", "updatedAt")
SELECT gen_random_uuid()::text, 'formula', '$S = \frac{wL^2}{8T}$', 'Sag of a Level Span', '$S = \frac{wL^2}{8T}\quad (\text{parabolic; span } L)$', '$\text{m}$', 'How far a conductor dips between level supports.', '[{"symbol":"$w$","meaning":"weight per unit length (or resultant loading)","unit":"$\\text{N/m}$"},{"symbol":"$L$","meaning":"span","unit":"$\\text{m}$"},{"symbol":"$T$","meaning":"horizontal tension","unit":"$\\text{N}$"}]'::jsonb, 'With half-span l: S = wl²/(2T). Close to the catenary when the sag is small.', 'EE', t."id", (SELECT s."id" FROM "SyllabusSubtopic" s JOIN "Topic" t ON t."id" = s."topicId" WHERE t."name" = 'Power System Analysis' AND t."subject" = 'EE' AND s."normKey" = 'sag and tension' AND s."active"), NULL, false, 'PENDING', now(), now()
FROM "Topic" t WHERE t."name" = 'Power System Analysis' AND t."subject" = 'EE'
ON CONFLICT ("kind", "subject", "name") DO NOTHING;
INSERT INTO "ReferenceCard" ("id", "kind", "symbol", "name", "formulaLatex", "valueUnit", "description", "variables", "purposeExamTip", "subject", "topicId", "subtopicId", "subtopicTag", "dimensionless", "status", "createdAt", "updatedAt")
SELECT gen_random_uuid()::text, 'formula', '$x_1 = \frac{L}{2} - \frac{Th}{wL}$', 'Supports at Different Levels', '$x_1 = \frac{L}{2} - \frac{Th}{wL},\quad x_2 = \frac{L}{2} + \frac{Th}{wL},\quad S_1 = \frac{wx_1^2}{2T},\ S_2 = \frac{wx_2^2}{2T}$', '$\text{m}$', 'Where the lowest point falls, and the sag from each support, on a sloping span.', '[{"symbol":"$h$","meaning":"height difference of the supports","unit":"$\\text{m}$"},{"symbol":"$x_1, x_2$","meaning":"distances from the lowest point to the lower and higher supports","unit":"$\\text{m}$"},{"symbol":"$T$","meaning":"horizontal tension","unit":"$\\text{N}$"}]'::jsonb, 'S₂ − S₁ = h. If x₁ comes out negative, the lowest point lies outside the span.', 'EE', t."id", (SELECT s."id" FROM "SyllabusSubtopic" s JOIN "Topic" t ON t."id" = s."topicId" WHERE t."name" = 'Power System Analysis' AND t."subject" = 'EE' AND s."normKey" = 'sag and tension' AND s."active"), NULL, false, 'PENDING', now(), now()
FROM "Topic" t WHERE t."name" = 'Power System Analysis' AND t."subject" = 'EE'
ON CONFLICT ("kind", "subject", "name") DO NOTHING;
INSERT INTO "ReferenceCard" ("id", "kind", "symbol", "name", "formulaLatex", "valueUnit", "description", "variables", "purposeExamTip", "subject", "topicId", "subtopicId", "subtopicTag", "dimensionless", "status", "createdAt", "updatedAt")
SELECT gen_random_uuid()::text, 'formula', '$w_r = \sqrt{(w + w_i)^2 + w_w^2}$', 'Ice and Wind Loading', '$w_i = \rho_i\pi t(d + t),\quad w_w = p(d + 2t),\quad w_r = \sqrt{(w + w_i)^2 + w_w^2}$', '$\text{N/m}$', 'The resultant load per metre when the conductor carries ice and wind.', '[{"symbol":"$t$","meaning":"radial ice thickness","unit":"$\\text{m}$"},{"symbol":"$d$","meaning":"conductor diameter","unit":"$\\text{m}$"},{"symbol":"$\\rho_i$","meaning":"ice weight density, about 8.9 kN/m³","unit":"$\\text{N/m}^3$"},{"symbol":"$p$","meaning":"wind pressure on the projected area","unit":"$\\text{Pa}$"}]'::jsonb, 'The sag then lies in the plane of w_r; its vertical part is S·(w + w_i)/w_r.', 'EE', t."id", (SELECT s."id" FROM "SyllabusSubtopic" s JOIN "Topic" t ON t."id" = s."topicId" WHERE t."name" = 'Power System Analysis' AND t."subject" = 'EE' AND s."normKey" = 'sag and tension' AND s."active"), NULL, false, 'PENDING', now(), now()
FROM "Topic" t WHERE t."name" = 'Power System Analysis' AND t."subject" = 'EE'
ON CONFLICT ("kind", "subject", "name") DO NOTHING;
INSERT INTO "ReferenceCard" ("id", "kind", "symbol", "name", "formulaLatex", "valueUnit", "description", "variables", "purposeExamTip", "subject", "topicId", "subtopicId", "subtopicTag", "dimensionless", "status", "createdAt", "updatedAt")
SELECT gen_random_uuid()::text, 'formula', '$L_c = L + \frac{8S^2}{3L}$', 'Conductor Length in a Span', '$L_c = L + \frac{8S^2}{3L},\qquad T_{support} \approx T + wS$', '$\text{m}$', 'The conductor needed for a span, and the tension at the supports.', '[{"symbol":"$L$","meaning":"span","unit":"$\\text{m}$"},{"symbol":"$S$","meaning":"sag","unit":"$\\text{m}$"},{"symbol":"$w$","meaning":"weight per length","unit":"$\\text{N/m}$"}]'::jsonb, 'A small change in length makes a big change in sag: why temperature matters so much.', 'EE', t."id", (SELECT s."id" FROM "SyllabusSubtopic" s JOIN "Topic" t ON t."id" = s."topicId" WHERE t."name" = 'Power System Analysis' AND t."subject" = 'EE' AND s."normKey" = 'sag and tension' AND s."active"), NULL, false, 'PENDING', now(), now()
FROM "Topic" t WHERE t."name" = 'Power System Analysis' AND t."subject" = 'EE'
